            survey.append(f"- {fs.path}\n  labels: {', '.join(fs.labels[:20])}\n  extracted: {fs.extracted_passages}; review: {fs.review_candidates}\n  date: {most_recent_date_signal(fs.date_signals)}\n  version: {', '.join(fs.version_signals[:8])}\n")
