    (DATA_DIR / "NATHAN_CORPUS_EXTRACTION_WARNINGS.txt").write_text("\n".join(warnings) + "\n" if warnings else "No warnings.\n", encoding="utf-8")
    write_status(len(files), scanned, len(all_passages), parts, surveys[-1].path if surveys else "", "complete", warnings, request)
