YEAR_RE = re.compile(r"\b(20\d{2}|19\d{2})\b")
VERSION_PATTERNS = [
    re.compile(r"\bSAT\s*(?:-|_)?\s*(?:Mark\s*)?[VvXxIi0-9]+\b"),
    re.compile(r"\bSAT\s*(?:-|_)?\s*[A-Z]\b"),
    re.compile(r"\bSAT[_\s-]*(?:XYZ|RMS|QG|O)\b", re.I),
