{"path":"/GitHub/link_6a1a5af1b40c8191affccbb98ac60fa3/create_file","args":{"repository_full_name":"Satobloc/SAT_THEORY_ARCHIVE_2023-25","path":"AI_AUTOMATION_ADMIN/_TOOLS/extract_nathan_corpus_labelled.py","message":"Add labelled Nathan extraction prototype","branch":"main","content":"#!/usr/bin/env python3
"""Label-guided Nathan words extractor.

Reads AI_AUTOMATION_ADMIN/AI_LABELS/nathan_extract_labels.txt.
Only labels marked X are extracted. Newly discovered labels are appended as _.
Writes compact editable extraction blocks with KEEP / EXTEND controls.
"""
from __future__ import annotations

import csv, hashlib, json, os, re, time
from collections import deque
from datetime import datetime, timezone
from pathlib import Path
from typing import Dict, List, Tuple

ROOT = Path(os.environ.get('GITHUB_WORKSPACE', '.')).resolve()
ADMIN = ROOT / 'AI_AUTOMATION_ADMIN'
LABELS_FILE = ADMIN / 'AI_LABELS' / 'nathan_extract_labels.txt'
REQUEST_FILE = ADMIN / 'AI_REQUESTS' / 'nathan_corpus_extract_request.json'
OUT = ROOT / '..NATHAN_WORDS_EXTRACTED'
LOGS = OUT / '_extraction_logs_and_indexes'
CURSOR = LOGS / 'crawl_cursor_labelled.json'
EXTRACT_LOG = LOGS / 'extraction_log.csv'
DISCOVERED_LOG = LOGS / 'discovered_labels.csv'

TEXT_EXT = {'.txt','.md','.markdown','.csv','.json','.jsonl','.yaml','.yml','.tex','.py','.js','.ts','.html','.htm','.xml','.rst','.log'}
SKIP_DIRS = {'.git','.github','AI_AUTOMATION_ADMIN','.AI_AUTOMATION_ADMIN','.⚙️_AI_AUTOMATION_ADMIN','..NATHAN_WORDS_EXTRACTED','..📚_NATHAN_WORDS_EXTRACTED','📚_NATHAN_WORDS_EXTRACTED','_NATHAN_CORPUS'}

DEFAULT_REQUEST = {
    'mode': 'extract',
    'max_runtime_seconds': 1200,
    'max_files_per_run': 2000,
    'max_dirs_per_run': 5000,
    'max_output_chars_per_run': 20000000,
    'max_chars_per_part': 200000,
    'max_single_passage_chars': 50000,
    'resume': True,
    'root_scan_dirs': ['.'],
}

# Candidate label: one to three words, optional repeated words/phrase, then delimiter.
# Allows light punctuation noise and supports Nathan/Näthan as literal text.
LABEL_RE = re.compile(r'''^\s*[#>*\-\[\]"'“”‘’() ]{0,5}(?P<label>(?:[A-Za-zÀ-ÖØ-öø-ÿ0-9_@.+]+\s+){0,5}[A-Za-zÀ-ÖØ-öø-ÿ0-9_@.+]+(?:\s+(?:said|says))?(?:\s+(?:said|says))?)(?:\s*(?::+|-+|—+|\.\.\.|…+)|\s*$).{0,5}\s*$''', re.X)
CONTROL_RE = re.compile(r'^<<<(?P<action>KEEP|DELETE)\s*\|\s*EXTEND\((?P<n>\d+)\)>>>$')


def now(): return datetime.now(timezone.utc).isoformat()
def rel(p: Path) -> str: return str(p.relative_to(ROOT)).replace(os.sep, '/')
def out_name(part: int) -> str: return f'{part:03d}_EXTRACTED_NATHAN_WORDS_PART_{part:03d}.txt'

def load_request() -> dict:
    req = dict(DEFAULT_REQUEST)
    if REQUEST_FILE.exists():
        try: req.update(json.loads(REQUEST_FILE.read_text(encoding='utf-8')))
        except Exception as e: req['request_error'] = str(e)
    return req

def canon_label(s: str) -> str:
    s = s.strip()
    s = s.replace('…','...').replace('—','-')
    s = re.sub(r'[:\-.]+\s*$', '', s)
    s = re.sub(r'\s+', ' ', s)
    # collapse doubled whole label, e.g. User said User said
    words = s.split()
    if len(words) % 2 == 0 and words[:len(words)//2] == words[len(words)//2:]:
        words = words[:len(words)//2]
    # collapse doubled terminal words, e.g. said said
    collapsed = []
    for w in words:
        if not collapsed or collapsed[-1].lower() != w.lower(): collapsed.append(w)
    return ' '.join(collapsed).strip().lower()

def display_label(line: str) -> str:
    m = LABEL_RE.match(line)
    if not m: return ''
    raw = m.group('label').strip()
    raw = re.sub(r'\s+', ' ', raw)
    return raw

def load_labels() -> Tuple[Dict[str,str], Dict[str,str]]:
    labels: Dict[str,str] = {}
    display: Dict[str,str] = {}
    if LABELS_FILE.exists():
        for line in LABELS_FILE.read_text(encoding='utf-8').splitlines():
            m = re.match(r'^\s*([X_\-])\s*\|\s*(.+?)\s*$', line)
            if not m: continue
            status, lab = m.group(1), m.group(2)
            c = canon_label(lab)
            if c:
                labels[c] = status
                display[c] = lab
    return labels, display

def save_labels(labels: Dict[str,str], display: Dict[str,str]) -> None:
    LABELS_FILE.parent.mkdir(parents=True, exist_ok=True)
    order = {'X':0, '_':1, '-':2}
    items = sorted(labels.items(), key=lambda kv: (order.get(kv[1],9), display.get(kv[0],kv[0]).lower()))
    text = []
    for c, status in items:
        text.append(f'{status} | {display.get(c,c)}')
    LABELS_FILE.write_text('\n'.join(text)+'\n', encoding='utf-8')

def is_text(path: Path) -> bool:
    return path.suffix.lower() in TEXT_EXT or (not path.suffix and path.name.upper() in {'README','LICENSE','NOTICE'})
def skip_dir(path: Path) -> bool: return path.name in SKIP_DIRS

def read_text(path: Path):
    for enc in ('utf-8','utf-8-sig','latin-1'):
        try: return path.read_text(encoding=enc), ''
        except UnicodeDecodeError: pass
        except Exception as e: return None, str(e)
    return None, 'decode failed'

def initial_cursor(req: dict) -> dict:
    roots=[]
    for r in req.get('root_scan_dirs') or ['.']:
        p=(ROOT/r).resolve()
        if p.exists() and p.is_dir(): roots.append('.' if p==ROOT else rel(p))
    return {'pending_dirs':roots,'pending_files':[],'completed_files':[],'completed_dirs':[],'next_part':0,'next_id':1,'runs':0,'created_utc':now(),'last_stop_reason':'init'}

def load_cursor(req: dict) -> dict:
    if req.get('resume', True) and CURSOR.exists():
        try: return json.loads(CURSOR.read_text(encoding='utf-8'))
        except Exception: pass
    return initial_cursor(req)

def save_cursor(cur: dict):
    LOGS.mkdir(parents=True, exist_ok=True)
    cur['updated_utc']=now()
    CURSOR.write_text(json.dumps(cur, indent=2, ensure_ascii=False)+'\n', encoding='utf-8')

def path_from_rel(r: str) -> Path: return ROOT if r=='.' else ROOT/r

def add_children(cur: dict, drel: str, counts: dict):
    d=path_from_rel(drel)
    for e in sorted(d.iterdir(), key=lambda p:p.name.lower()):
        if e.is_symlink(): continue
        if e.is_dir():
            if skip_dir(e): counts['dirs_skipped']+=1
            else: cur['pending_dirs'].append(rel(e)); counts['dirs_found']+=1
        elif e.is_file():
            if is_text(e): cur['pending_files'].append(rel(e)); counts['files_found']+=1
            else: counts['files_skipped']+=1

def date_signal(text: str) -> str:
    m = re.search(r'\b(20\d{2}|19\d{2})[-/\.](\d{1,2})[-/\.](\d{1,2})\b', text)
    if m: return f'{int(m.group(1)):04d}-{int(m.group(2)):02d}-{int(m.group(3)):02d}'
    y = re.findall(r'\b(20\d{2}|19\d{2})\b', text)
    return max(y) if y else ''

def version_signal(text: str) -> str:
    m = re.search(r'\bSAT\s*(?:-|_)?\s*(?:Mark\s*)?[A-Za-z0-9]+\b', text)
    return m.group(0) if m else ''

def split_segments(lines: List[str], labels: Dict[str,str], display: Dict[str,str], source: str):
    candidates=[]
    for i,line in enumerate(lines):
        lab=display_label(line)
        if not lab: continue
        c=canon_label(lab)
        if not c: continue
        if c not in labels:
            labels[c]='_'; display[c]=lab
        candidates.append((i+1, lab, c))
    segs=[]
    for idx,(start,lab,c) in enumerate(candidates):
        end = (candidates[idx+1][0]-1) if idx+1 < len(candidates) else len(lines)
        text='\n'.join(lines[start:end]).strip('\n')
        stop_lab = candidates[idx+1][1] if idx+1 < len(candidates) else 'EOF'
        segs.append({'start':start,'end':end,'label':lab,'canon':c,'text':text,'stop':stop_lab})
    return segs

def passage_block(pid: str, seg: dict, source: str, file_text: str, max_chars: int):
    text = seg['text']
    if len(text)>max_chars: text=text[:max_chars]+'\n\n[TRIMMED BY max_single_passage_chars]'
    ds = date_signal(text) or date_signal(file_text[:20000])
    vs = version_signal(text) or version_signal(source)
    top = f'<<<START_{pid}' + (f' {ds}' if ds else '') + (f' [{vs}]' if vs else '') + '>>>'
    src = f'<<<EX_SRC: {source} LINES: {seg["start"]}-{seg["end"]} LABEL: {seg["label"]}>>>'
    end = f'<<<END_{pid} STOPPED_BY: {seg["stop"]}>>>'
    return top+'\n'+src+'\n\n'+text.rstrip()+'\n\n<<<KEEP | EXTEND(0)>>>'+'\n'+end+'\n\n'

def append_output(blocks: List[str], cur: dict, req: dict, counts: dict):
    if not blocks: return
    max_part=int(req['max_chars_per_part'])
    max_total=int(req['max_output_chars_per_run'])
    buf=[]; chars=0
    def flush():
        nonlocal buf, chars
        if not buf: return
        part=int(cur.get('next_part',0))
        (OUT/out_name(part)).write_text(''.join(buf), encoding='utf-8')
        cur['next_part']=part+1; counts['parts_written']+=1; buf=[]; chars=0
    for b in blocks:
        if counts['output_chars']+len(b)>max_total:
            counts['stop_reason']='max_output_chars_per_run'; break
        if buf and chars+len(b)>max_part: flush()
        buf.append(b); chars+=len(b); counts['output_chars']+=len(b)
    flush()

def log_rows(path: Path, rows: List[dict], fields: List[str]):
    if not rows: return
    exists=path.exists(); path.parent.mkdir(parents=True, exist_ok=True)
    with path.open('a', encoding='utf-8', newline='') as f:
        w=csv.DictWriter(f, fieldnames=fields)
        if not exists: w.writeheader()
        for r in rows: w.writerow(r)

def process_file(path: Path, labels: Dict[str,str], display: Dict[str,str], cur: dict, req: dict, counts: dict):
    text,err=read_text(path)
    source=rel(path)
    if text is None: return [], [{'source':source,'warning':err}]
    lines=text.splitlines()
    segs=split_segments(lines, labels, display, source)
    blocks=[]; log=[]; discovered=[]
    for seg in segs:
        discovered.append({'label':seg['label'],'canon':seg['canon'],'status':labels.get(seg['canon'],'_'),'source':source,'line':seg['start']})
        if labels.get(seg['canon'])!='X': continue
        raw_hash=hashlib.sha1((source+str(seg['start'])+seg['label']+seg['text']).encode('utf-8','ignore')).hexdigest()
        pid=f'EX-{int(cur.get("next_id",1)):09d}'
        cur['next_id']=int(cur.get('next_id',1))+1
        blocks.append(passage_block(pid, seg, source, text, int(req['max_single_passage_chars'])))
        log.append({'passage_id':pid,'source':source,'start_line':seg['start'],'end_line':seg['end'],'label':seg['label'],'stop_label':seg['stop'],'hash':raw_hash,'run_utc':now()})
    counts['passages_extracted']+=len(blocks)
    return blocks, log, discovered

def write_status(cur: dict, req: dict, counts: dict):
    OUT.mkdir(parents=True, exist_ok=True); LOGS.mkdir(parents=True, exist_ok=True)
    text=f'''# Nathan labelled extraction\n\nStatus: {counts.get('status','paused')}\nStop reason: {counts.get('stop_reason','')}\nGenerated UTC: {now()}\n\nThis run:\n- files processed: {counts['files_processed']}\n- dirs processed: {counts['dirs_processed']}\n- passages extracted: {counts['passages_extracted']}\n- output parts written: {counts['parts_written']}\n- output chars: {counts['output_chars']}\n\nCursor:\n- pending dirs: {len(cur.get('pending_dirs',[]))}\n- pending files: {len(cur.get('pending_files',[]))}\n- next part: {cur.get('next_part',0)}\n- next id: {cur.get('next_id',1)}\n\nOpen numbered extraction files in this folder. Edit KEEP to DELETE or EXTEND(0) to EXTEND(N) for cleanup/repair workflow.\n'''
    (OUT/'000_START_HERE_STATUS.txt').write_text(text, encoding='utf-8')

def main():
    OUT.mkdir(parents=True, exist_ok=True); LOGS.mkdir(parents=True, exist_ok=True)
    req=load_request(); labels,display=load_labels(); cur=load_cursor(req); start=time.monotonic()
    counts={'files_processed':0,'dirs_processed':0,'files_found':0,'dirs_found':0,'files_skipped':0,'dirs_skipped':0,'passages_extracted':0,'parts_written':0,'output_chars':0,'stop_reason':''}
    while True:
        if time.monotonic()-start >= int(req['max_runtime_seconds']): counts['stop_reason']='max_runtime_seconds'; break
        if counts['files_processed'] >= int(req['max_files_per_run']): counts['stop_reason']='max_files_per_run'; break
        if counts['dirs_processed'] >= int(req['max_dirs_per_run']): counts['stop_reason']='max_dirs_per_run'; break
        if counts.get('stop_reason'): break
        if cur.get('pending_files'):
            frel=cur['pending_files'].pop(0); p=path_from_rel(frel)
            if p.exists() and p.is_file():
                blocks, log, disc = process_file(p, labels, display, cur, req, counts)
                append_output(blocks, cur, req, counts)
                log_rows(EXTRACT_LOG, log, ['passage_id','source','start_line','end_line','label','stop_label','hash','run_utc'])
                log_rows(DISCOVERED_LOG, disc, ['label','canon','status','source','line'])
                cur['completed_files'].append(frel); counts['files_processed']+=1
        elif cur.get('pending_dirs'):
            drel=cur['pending_dirs'].pop(0); d=path_from_rel(drel)
            if d.exists() and d.is_dir(): add_children(cur,drel,counts); cur['completed_dirs'].append(drel); counts['dirs_processed']+=1
        else:
            counts['stop_reason']='crawl_complete'; break
    cur['runs']=int(cur.get('runs',0))+1; cur['last_stop_reason']=counts['stop_reason']; save_cursor(cur); save_labels(labels,display)
    counts['status']='complete' if counts['stop_reason']=='crawl_complete' else 'paused_by_limit'
    write_status(cur,req,counts)
    return 0
if __name__=='__main__': raise SystemExit(main())
